import{c as t,Q as o,j as r,m as d}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Claude 5 世代的 Context Engineering 新規則","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/46-context-engineering-claude5.md","filePath":"research/best-practices/46-context-engineering-claude5.md","lastUpdated":1785909234000}'),a={name:"research/best-practices/46-context-engineering-claude5.md"};function n(c,e,s,i,l,p){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-5-世代的-context-engineering-新規則" tabindex="-1">Claude 5 世代的 Context Engineering 新規則 <a class="header-anchor" href="#claude-5-世代的-context-engineering-新規則" aria-label="Permalink to &quot;Claude 5 世代的 Context Engineering 新規則&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/the-new-rules-of-context-engineering-for-claude-5-generation-models" target="_blank" rel="noreferrer">The new rules of context engineering for Claude 5 generation models</a>（2026-07-24） 整理日期：2026-08-04 <strong>canonical 落點</strong>：本 workspace 的完整校準與剪枝判準在 <code>.claude/refs/context-engineering-claude5.md</code>（L2 SSoT）。本檔只保留官方原文重點，供 corpus 追溯，<strong>不重複該檔的 workspace 對應表</strong>。</p></blockquote><hr><h2 id="官方實證錨點" tabindex="-1">官方實證錨點 <a class="header-anchor" href="#官方實證錨點" aria-label="Permalink to &quot;官方實證錨點&quot;">​</a></h2><p>Anthropic 為 Claude Opus 5 / Fable 5 <strong>刪掉了 Claude Code system prompt 的 80% 以上</strong>，在其 coding evals 上<strong>無可量測退化</strong>。</p><p>根因：舊 prompt 對模型 over-constrain，且指令彼此打架——同一次請求裡同時出現「leave documentation as appropriate」與「DO NOT add comments」。新世代模型會花推理預算去調解衝突訊息，所以「多加一條保險條文」不是零成本。</p><hr><h2 id="六條-then-→-now" tabindex="-1">六條 Then → Now <a class="header-anchor" href="#六條-then-→-now" aria-label="Permalink to &quot;六條 Then → Now&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>規則</th><th>內容</th></tr></thead><tbody><tr><td>1</td><td>Judgment over rules</td><td>用「寫得像周遭程式碼」取代硬性條數禁令，讓模型判斷</td></tr><tr><td>2</td><td>Tool design over examples</td><td>與其給使用範例（會限縮探索），不如把參數設計得有表達力、enumeration 清楚（<code>status: pending/in_progress/completed</code>）</td></tr><tr><td>3</td><td>Progressive disclosure over upfront info</td><td>驗證與 code review 指導從 system prompt 移出，改成 Claude 需要時才呼叫的 Skill；部分工具改 <strong>deferred loading</strong>（先 <code>ToolSearch</code> 取 schema 才可呼叫）</td></tr><tr><td>4</td><td>Simplified descriptions over repetition</td><td>同一指令不要在 system prompt 與 tool description 重覆；指令的正確歸宿是 tool description</td></tr><tr><td>5</td><td>Auto-memory over manual saving</td><td>新世代自動保留相關記憶，不必事事用 <code>#</code> 熱鍵手寫進 CLAUDE.md</td></tr><tr><td>6</td><td>Rich references over simple specs</td><td>除了 markdown 規格，也吃 HTML artifact / test suite / code sample / rubric</td></tr></tbody></table><hr><h2 id="context-assembly-四層" tabindex="-1">Context Assembly 四層 <a class="header-anchor" href="#context-assembly-四層" aria-label="Permalink to &quot;Context Assembly 四層&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>承載</th></tr></thead><tbody><tr><td>System prompt</td><td>產品脈絡與核心目的（平台持有）</td></tr><tr><td>CLAUDE.md</td><td>輕量 repo 描述 + critical gotchas</td></tr><tr><td>Skills</td><td>編碼團隊意見的輕量指南</td></tr><tr><td>References</td><td>code sample / spec / mockup / test suite</td></tr></tbody></table><p>工具：<code>/doctor</code> 可對現有 context 提出 rightsize 建議（v2.1.206 起會主動提案 <code>CLAUDE.md</code> 精簡）。</p><hr><h2 id="重要邊界-本-workspace-立場" tabindex="-1">重要邊界（本 workspace 立場） <a class="header-anchor" href="#重要邊界-本-workspace-立場" aria-label="Permalink to &quot;重要邊界（本 workspace 立場）&quot;">​</a></h2><p><strong>驗證閘門不在「可刪的鷹架」之列。</strong> 能力提升不得換取更少驗證（<code>core.md</code> 能力悖論）。可刪的是為補償模型弱點而堆的程序性鷹架，不是 <code>[E]</code> 閘門與不可逆操作確認。</p><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>.claude/refs/context-engineering-claude5.md</code> — L2 校準 + 剪枝判準（workspace canonical）</li><li><code>47-verification-loops-skills.md</code> — 被移出 system prompt 的驗證指導長什麼樣</li><li><code>21-memory-claudemd.md</code> · <code>38-steering-claude-code.md</code> — CLAUDE.md 與行為調整機制</li></ul>',19)])])}const u=t(a,[["render",n]]);export{m as __pageData,u as default};
